Definition ex_side (LF : list fframe) (m : mem) (lo shi ff fp TL T SP TP n k : Z) : Prop :=
  as_RFS H ((1, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi
  /\ accessible m TL 16 /\ accessible m T 16 /\ accessible m SP n /\ accessible m TP k
  /\ accessible m (ff + 32) 40.
