Definition ex_client (m' : mem) (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) : Prop :=
  rw_cells bsegs m' TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)
  /\ rw_cells bsegs m' T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at bsegs m' SP sbs /\ bytes_at bsegs m' TP tbs
  /\ accessible m' TL 16 /\ accessible m' T 16
  /\ accessible m' SP (Z.of_nat (length sbs)) /\ accessible m' TP (Z.of_nat (length tbs)).

