(* [comment removed for export] *)
Definition ex_sep (A n ff fp : Z) : Prop :=
  (A + n <= ff \/ ff + 128 <= A)
  /\ (A + n <= Z.shiftr ff 3 + 2147450880 \/ Z.shiftr ff 3 + 2147450880 + 16 <= A)
  /\ (A + n <= fp \/ fp + 1 <= A).

(* [comment removed for export] *)
Definition ex_ctx (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v : word)
    (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) (lo shi ff fp : Z)
    (h0 h1 h2 h3 : word) (fj sh16 : list byte) (ebc resc itc : list cell) : Prop :=
  rw_cells bsegs m1 spa [C8 (wz ff)]
  /\ rw_cells bsegs m1 (spa + 8) ebc
  /\ rw_cells bsegs m1 (spa + 48) (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
  /\ rw_cells bsegs m1 (spa + 88) resc
  /\ rw_cells bsegs m1 (spa + 128) [CB gsz gj]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -96) (ex_saved s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav)
  /\ rw_cells bsegs m1 ff [C8 h0; C8 h1; C8 h2; C8 h3]
  /\ rw_cells bsegs m1 (ff + 32) itc
  /\ rw_cells bsegs m1 (ff + 72) [CB 48 fj; C8 (wz fp)]
  /\ rw_cells bsegs m1 (Z.shiftr ff 3 + 2147450880) [CB 16 sh16]
  /\ rw_cells bsegs m1 fp [C1 (b8 1)]
  /\ rw_cells bsegs m1 TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)
  /\ rw_cells bsegs m1 T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at bsegs m1 SP sbs /\ bytes_at bsegs m1 TP tbs
  /\ stk bsegs m1 lo spa
  /\ munch (ex_W H lo sp ff fp) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ ex_side LF m1 lo shi ff fp TL T SP TP (Z.of_nat (length sbs)) (Z.of_nat (length tbs)).

Definition ex_pure (sp : word) (spa : Z) (gsz : nat) (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell)
    (lo shi ff fp : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ TP + Z.of_nat (length tbs) < 2^64
  /\ lo + AEXISTS_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= TL \/ TL + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)) <= lo)
  /\ (bv_unsigned sp <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ (bv_unsigned sp <= TP \/ TP + Z.of_nat (length tbs) <= lo)
  /\ bv_unsigned sp + 64 <= shi /\ TL mod 8 = 0 /\ T mod 8 = 0
  /\ spa + 128 + Z.of_nat gsz = bv_unsigned sp + -96 /\ bv_unsigned sp - 240 <= spa /\ spa mod 8 = 0
  /\ ex_sep TL (Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest))) ff fp
  /\ ex_sep T (Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest))) ff fp
  /\ ex_sep SP (Z.of_nat (length sbs)) ff fp /\ ex_sep TP (Z.of_nat (length tbs)) ff fp
  /\ ((0 < length sbs)%nat -> 0 < SP) /\ ((0 < length tbs)%nat -> 0 < TP).                (* [comment removed for export] *)

