Lemma ex_client_retire : forall LF mx m' lo shi ff fp TL T SP TP (sbs tbs : list byte) (tlrest trest : list cell),
  ex_side LF mx lo shi ff fp TL T SP TP (Z.of_nat (length sbs)) (Z.of_nat (length tbs)) ->
  rw_cells bsegs mx TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest) ->
  rw_cells bsegs mx T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest) ->
  bytes_at bsegs mx SP sbs -> bytes_at bsegs mx TP tbs ->
  ex_sep TL (Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest))) ff fp ->
  ex_sep T (Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest))) ff fp ->
  ex_sep SP (Z.of_nat (length sbs)) ff fp -> ex_sep TP (Z.of_nat (length tbs)) ff fp ->
  munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono bsegs mx m' ->
  ex_client m' TL T SP TP sbs tbs tlrest trest.
