Ltac open_ectx HH sp CTX PURE :=
  destruct CTX as (L & EB & EA & RES & GAP & SAV & FH & IT & FT & SHU & FL & TLC & TC & WS & WT & ST & MU & WM & MI & SD);
  destruct PURE as (SP64 & TP64 & LO & CEIL & SEP1 & SEP2 & SEP3 & SEP4 & SHI & TLAL & TAL & GAPE & SPA1 & SPA8 & DTL & DT & DSP & DTP & NZS & NZT);
  destruct (ex_ff_nums _ HH _ _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & N1 & N2 & N3 & N4 & N5 & N6 & N7 & NSF & NSP);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TLC) as TLB; cbn [cells_size csize] in TLB, SEP1;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize] in TCB, SEP2;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  (let D := fresh "DTL1" in pose proof DTL as (D & _ & _); cbn [cells_size csize] in D);
  (let D := fresh "DT1" in pose proof DT as (D & _ & _); cbn [cells_size csize] in D);
  (let D := fresh "DSP1" in pose proof DSP as (D & _ & _));
  (let D := fresh "DTP1" in pose proof DTP as (D & _ & _));
  hyde_disj; hydeL TLAL; hydeL TAL; hydeL SPA8; hydeL N3;
  unfold TokItCells, AEXISTS_STACK, FINDIF_STACK, TOKIT_STACK, AINTRIN_STACK, ex_W, ex_saved, AFS_FLAGS in *.

(* [comment removed for export] *)
Ltac ex_call_ctor_stack HH CTOR A Fi SP sbs cs EBH NZS :=
  lazymatch goal with
  | SD : ex_side ?H ?LF ?mc ?lo ?shi ?ff ?fp ?TL ?T _ ?TP ?n ?k, ST : stk _ ?mc ?lo ?spa, WS : bytes_at _ ?mc SP sbs, MI : mem_inv _ ?mc,
    CEIL : aceil <= ?lo |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let CS := fresh "CS" in let AO := fresh "AO" in let MU2 := fresh "MU2" in let WM2 := fresh "WM2" in
    let AC := fresh "ACc" in let SK := fresh "SKc" in let AW := fresh "AWc" in
    pose proof SD as (_ & AC & SK & _ & _ & AW & _ & _);
    assert (AO : aobj mc A 40) by (eapply (aobj_stack mc lo shi); [exact SK | lia | lia | lia]);
    clear SK;
    pose proof (munch_refl [(lo, spa + 128); (ff, ff + 128)]%Z mc) as MU2; pose proof (wmono_refl bsegs mc) as WM2;
    pose proof CTOR as CS; unfold tokit_ctor_stmt, tokit_ctor_post, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, P_A_TOKEN_LIST_ITER_CTOR in CS;
    callZc (CS A Fi (SP + Z.of_nat (length sbs)) SP lo sbs cs) (clear CS EBH ST WS AC AO AW);
    [ exact EBH | first [reflexivity | assumption] | exact WS | lia | reflexivity | lia
    | dj_lia
    | rewrite ?unsigned_lit by lia; exact ST | rewrite ?unsigned_lit by lia; lia | exact CEIL
    | rewrite ?unsigned_lit by lia; left; lia
    | rewrite ?unsigned_lit by lia; dj_lia
    | exact MI | exact AC | exact AO | first [assumption | unhideL; Z.div_mod_to_equations; lia] | exact AW | exact NZS | ];
    repeat match goal with Hx : ACONST _ |- _ => clear Hx | Hx : aobj _ _ _ |- _ => clear Hx end;
    lazymatch goal with MU2' : munch _ mc ?m', WM2' : wmono _ mc ?m' |- evt _ _ (MS _ _ _ _ _ ?m' _) =>
      let SD' := fresh "SD" in
      assert (SD' : ex_side H LF m' lo shi ff fp TL T SP TP n k)
        by (eapply (ex_side_step H HH LF _ mc m'); [exact SD | exact MU2' | exact WM2' |];
            apply Forall_cons; [left; cbn [fst]; exact CEIL | apply Forall_cons; [right; cbn [fst snd]; lia | apply Forall_nil]]);
      clear SD MU2' WM2'; rename SD' into SD;
      repeat match goal with Hx : accessible ?mo _ _ |- _ => lazymatch mo with m' => clear Hx end end
    end;
    lazymatch goal with Hx : rw_cells _ _ A _ |- _ => rename Hx into EBH end;
    lazymatch goal with Hx : bytes_at _ _ SP sbs |- _ => rename Hx into WS end;
    lazymatch goal with Hx : stk _ _ lo _ |- _ => rename Hx into ST end;
    lazymatch goal with Hx : mem_inv _ _ |- _ => rename Hx into MI end
  end.

(* [comment removed for export] *)
Ltac ex_end_checks K :=
  zstep; try (rewrite (Z.add_comm (Z.of_nat (length _)) _));
  notrap; K; zstep; zstep; zstep; rewrite nullbase_xor by lia; notrap.

Section TAIL.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis CTOR : tokit_ctor_stmt.
Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.

(* [comment removed for export] *)
Lemma ex_tail : forall (v : bool) (vp vl itv Fv : Z) rax ra sp gp tp t0 t1 t2 a0x a1x a2x a3x a4x a5x a6x a7x s6x t3 t4 t5 t6
    (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11 : word)
    (F : bvmap 5 word) fc (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj : list byte)
    (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) (lo shi ff fp : Z) (h0 h1 h2 h3 : word) (fj sh16 : list byte)
    (ebc : list cell),
  ex_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v TL T SP TP sbs tbs tlrest trest lo shi ff fp
         h0 h1 h2 h3 fj sh16 ebc (TokItCells vp vl itv Fv (SP + Z.of_nat (length sbs))) (TokItCells vp vl itv Fv (SP + Z.of_nat (length sbs))) ->
  ex_pure sp spa gsz TL T SP TP sbs tbs tlrest trest lo shi ff fp ->
  cells_size ebc = 40%nat -> 0 <= itv < 2^64 -> 0 <= Fv < 2^64 ->
  v = negb ((itv =? SP + Z.of_nat (length sbs)) && (Fv =? SP + Z.of_nat (length sbs))) ->
  evt bsegs (ex_post_v H v ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11 F fc TL T SP TP sbs tbs tlrest trest LF lo shi m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (wz spa) a0x a1x a2x a3x a4x a5x a6x a7x
              (wz ff) (wz TL) (wz T) (wz (TL + 8)) s6x (wz (Z.shiftr ff 3 + 2147450880)) (wz ff)
              (wz (Z.shiftr TL 3 + 2147450880)) (wz (Z.shiftr (TL + 8) 3 + 2147450880)) s11 t3 t4 t5 t6)
